import axios from 'axios';

// Create separate axios instances for each service
const createApiInstance = (baseUrl) => {
  const instance = axios.create({
    baseURL: `${baseUrl}/api/v1`,
    headers: { 'Content-Type': 'application/json' },
  });

  // Attach JWT token to all requests
  instance.interceptors.request.use((config) => {
    const token = localStorage.getItem('medibook_token');
    if (token) config.headers.Authorization = `Bearer ${token}`;
    return config;
  });

  return instance;
};

const appointmentApi = createApiInstance(process.env.REACT_APP_API_URL || 'http://localhost:5169');
const authApi = createApiInstance(process.env.REACT_APP_AUTH_SERVICE_URL || 'http://localhost:5036');
const providerApi = createApiInstance(process.env.REACT_APP_PROVIDER_SERVICE_URL || 'http://localhost:5268');
const availabilityApi = createApiInstance(process.env.REACT_APP_AVAILABILITY_SERVICE_URL || 'http://localhost:5211');
const paymentApi = createApiInstance(process.env.REACT_APP_PAYMENT_SERVICE_URL || 'http://localhost:5289');
const notificationApi = createApiInstance(process.env.REACT_APP_NOTIFICATION_SERVICE_URL || 'http://localhost:5134');
const recordApi = createApiInstance(process.env.REACT_APP_RECORD_SERVICE_URL || 'http://localhost:5174');
const reviewApi = createApiInstance(process.env.REACT_APP_REVIEW_SERVICE_URL || 'http://localhost:5071');

// Appointment endpoints
export const appointmentService = {
  book: (data) => api.post('/appointments', data),
  getById: (id) => api.get(`/appointments/${id}`),
  getByPatient: (patientId) => api.get(`/appointments/patient/${patientId}`),
  getUpcomingByPatient: (patientId) => api.get(`/appointments/patient/${patientId}/upcoming`),
  getByProvider: (providerId) => api.get(`/appointments/provider/${providerId}`),
  getByProviderAndDate: (providerId, date) =>
    api.get(`/appointments/provider/${providerId}/date/${date}`),
  cancel: (id) => api.put(`/appointments/${id}/cancel`),
  reschedule: (id, data) => api.put(`/appointments/${id}/reschedule`, data),
  complete: (id) => api.put(`/appointments/${id}/complete`),
  updateStatus: (id, status) => api.put(`/appointments/${id}/status`, JSON.stringify(status)),
  getProviderCount: (providerId) => api.get(`/appointments/provider/${providerId}/count`),
};

export default api;
